package com.wizzadrds.theworldremembers.voice; public record VoiceSpatial(double x,double y,double z,float maxDistance,float volume){public VoiceSpatial{if(maxDistance<=0||volume<0)throw new IllegalArgumentException();} public float attenuation(double lx,double ly,double lz){double d=Math.sqrt(Math.pow(lx-x,2)+Math.pow(ly-y,2)+Math.pow(lz-z,2));return d>=maxDistance?0f:(float)Math.max(0,volume*(1-d/maxDistance));}}